package it.unibo.jakta.agent

import it.unibo.jakta.event.AgentEvent
import it.unibo.jakta.event.EventInbox
import it.unibo.jakta.event.EventStream

/**
 * The view on an [Agent] from the [AgentLifecycle] perspective.
 */
interface ExecutableAgent<Belief : Any, Goal : Any> : Agent {
    /**
     * [AgentEvent] stream emitted by the agent.
     * Includes both [AgentEvent.Internal] either generated by the [MutableAgentState] or received from the [internalInbox]
     * and [AgentEvent.External] generated from the [it.unibo.jakta.node.Node]
     */
    val events: EventStream<AgentEvent>

    /**
     * An inbox of [AgentEvent.Internal] that the [AgentLifecycle] can use
     * to send events that allows the agent to advance.
     */
    val internalInbox: EventInbox<AgentEvent.Internal>

    /**
     * The mutable state of the agent.
     */
    val state: MutableAgentState<Belief, Goal>

    /**
     * Resumes the intentions [waiting][MutableAgentState.waitForEvent] for [event]: those whose filter returns a
     * non-null value for it. The [AgentLifecycle] calls it after handling an event, so that the waiting intentions
     * see the state the event produced.
     * @param event the event the agent handled.
     */
    fun resumeWaiting(event: AgentEvent)
}
